def find_longest_subarray(n, elements):
    elements_count = {}
    for elem in elements:
        elements_count[elem] = elements_count.get(elem, 0) + 1

    max_length = 0
    current_length = 1
    for i in range(n):
        max_length = max(max_length, current_length)
        if i < n - 1 and elements_count[elements[i]] == elements_count[elements[i + 1]]:
            current_length = current_length + 1
        else:
            current_length = 2

    max_length = max(max_length, current_length)
    return max_length

