import math

def get_closest_perfect_power(n):
    if math.isqrt(n) ** 2 == n:
        return n
    low, high = 1, n
    while low < high:
        mid = (low + high) // 2
        if mid ** (1 + int(math.log(mid, mid))) == n:
            return n
        elif mid ** (1 + int(math.log(mid, mid))) < n:
            low = mid
        else:
