import math

def closest_perfect_power(n):
    lower = 2
    upper = n
    if n == 1:
        return 1
    while lower <= upper:
        mid = int((lower + upper) / 2)
        power = mid ** (2 / 3)
        if math.isqrt(power) ** 3 == power:
            return mid ** 3
        elif mid ** 3 < n:
            lower = mid + 1
        else:
            upper = mid - 1
