def max_length_of_subarray_with_unique_most_frequent_value(n, array):
    count_values = {}
    start = 0
    end = 0
    max_length = 0
    current_most_frequent = 1

    while end < n:
        if array[end] in count_values:
            count_values[array[end]] += 1
        else:
            count_values[array[end]] = 1

        while current_most_frequent > 1 and start < n:
            if count_values[array[start]] == 1:
                count_values.pop(array[start])
            else:
                count_values[array[start]] -= 1
                if count_values[array[start]] == 0:
                    count_values.pop(array[start])
            current_most_frequent = max(count_values.values())

            if current_most_frequent <= 1:
                current_most_frequent = 1
                start += 1
            else:
                end += 1

        max_length = max(max_length, end - start + 1)

    return max_length

