def solve_problem(n, s, program):
    pos = []
    pos_taken = [False] * n

    for i in range(n):
        line = program[i]
        if line.startswith('set'):
            y, v = map(int, line.split()[1:])
            if not pos_taken[i]:
                pos.append(i)
                pos_taken[i] = True
        elif line.startswith('if'):
            if int(line.split()[1]) != s:
                pos.append(i)
                pos_taken[i] = True

    ans = 0
    for i in range(n):
        if i in pos:
            ans -= 1  # Each 'set y v' instruction costs 1 burle to remove
    return n - pos.count(False) - ans

