    color_used = [False] * len(tree)
    used = set()

    def dfs(x, prev):
        color_map[x] = 1
        if color_used[x]:
            return
        if color_map[x] is None:
            return
        for y in tree[x]:
            if y == prev:
                continue
            if color_map[y] is not None:
                continue
            if y not in used:
                dfs(y, x)
        used.add(x)

    for _, c, d in edges:
        dfs(c, -1)
        dfs(d, -1)

    if any(x is None for x in color_used):
        return "NO"

    for i, (c, d, u, v) in enumerate(edges):
        if color_map[c] != color_map[d] and (c, d) != (u, v):
