def bellman_ford(V, edges):
    distances = [float('inf')] * V
    distances[0] = 0
    shortest_paths = [float('inf')] * V

    for _ in range(V - 1):
        for u, v, w in edges:
            if distances[u] + w < distances[v]:
                if distances[v] == float('inf'):
                    shortest_paths[v] = distances[u]
                distances[v] = distances[u] + w

    # Check for negative cycles
    for u, v, w in edges:
        if distances[u] + w < distances[v]:
            raise ValueError('Graph contains a negative cycle')

    return shortest_paths


def count_travelling_plans(V, N, edges):
    distances = bellman_ford(V, edges)
    paths = [math.comb(N, i) for i in range(N + 1)]

    for steps in range(1, V):
        paths = [2 * x - 1 for x in paths]
        paths = [
            (path + 1) * paths[steps - 1] * (paths[steps - 2] // (i + 1))
            for path, i in zip(paths, range(steps, V - 1)) if i % 2
        ]
        paths = [
            ((path + 1) - paths[steps] + 1) * paths[steps - 1] * (paths[steps - 2] // (i + 1))
            for path, i in zip(paths, range(steps - 2, -1, -1)) if i % 2
        ]

    return sum(path % (10**9 + 9) for path in paths if path % (10**9 + 9) > 0)


