import sys

class OdtTree:
    def __init__(self, n: int):
        self.n = n
        self.colors = [0] * (n + 2)
        self.edges = defaultdict(list)
        self.modifications = []

    def read_input(self):
        n, m = map(int, input().split())
        self.n = n
        self.m = m

        self.colors = list(map(int, input().split()))
        for _ in range(n - 1):
            u, v = map(int, input().split())
            self.edges[u].append(v)
            self.edges[v].append(u)

    def init_graph(self):
        for u in range(1, self.n + 1):
            for v in self.edges[u]:
                if u < v:
                    self.edges[v].append(u)
                else:
                    self.edges[u].append(v)

    def process_modifications(self):
        for _ in range(self.m):
            u, x = map(int, input().split())
            self.modifications.append((u, x))

    def calculate_path_sum(self):
        path_colors = [1] * (self.n + 1)
        for u, v in enumerate(self.modifications, start=1):
            path_colors[u] *= self.colors[v[0]]
            path_colors[v[0]] *= self.colors[u]

        for u, v in self.edges.items():
            neighbor_colors = self.colors[u]
            total_sum = (self.n * neighbor_colors) - self.colors[v[0]] * (len(v) - 1)
            for w in v:
                if u < w:
                    neighbor_colors = path_colors[w]
                    total_sum += neighbor_colors
                    neighbor_colors = self.colors[u]
                else:
                    neighbor_colors = self.colors[w]
                    total_sum += neighbor_colors

            path_colors[u] += neighbor_colors * (2 ** w - 1)

        return sum(path_colors[1:])


if __name__ == "__main__":
