def count_subsequences(n, m, s):
    if m == 1:
        return 2 ** (n - 1) - 2  # Only '', 'a' and 'b'
    elif m == 2:
        dp = [0, 1] + [0] * (n - 1)
        for i in range(2, n + 1):
            dp[i] = dp[i - 1] + (2 ** (i - 2))
        return dp[n]
    else:
        dp = [0] * (n + 1)
        for i in range(m):
            for j in range(n):
                if i < j:  # Invalid case
                    dp[j + 1] = (2 ** (j - 1) - (2 ** (j - i - 1))) + sum(dp[i + 1:j + 1])
                else:  # Invalid case
                    dp[j + 1] = sum(dp[1:j + 1])
