from numpy import inf

def max_non_unique_max_count(arr, n):
    freq_map = Counter(arr)
    max_count = 0
    for val, count in freq_map.items():
        max_count = max(max_count, count)

    if max_count & 1:
        return 0

    min_k = min(freq_map, key=lambda x: arr.count(x))  # The key here is finding unique counts

    if freq_map[min_k] > (n // 2):
        k = n // 2
    else:
        k = freq_map[min_k]

    max_subarray_len = 0
    left, right = 0, 0

    for right in range(n):
        if freq_map[arr[right]] == k:
            max_subarray_len = max(max_subarray_len, right - left + 1)
            while freq_map[arr[left]] == k:
                freq_map[arr[left]] -= 1
                left += 1
    return max_subarray_len

