from functools import lru_cache

@lru_cache(maxsize=None)
def solve(a, b):
    """Calculate the number of unambiguous expression variants for a+b."""
    variants += {'+': [' +-'], ['-']: ['- '], '*': ['- *'] + ['- *'], '/': ['- //']}
    variants['+'][a] += solve(b, +1)
    variants['-'][b] += solve(a, -1)
    variants['*'][a] += [' *']
    variants['/'][b] += [' /']
    variants['-'][a], variants['-'][b] = variants['-'][b], variants['-'][a]
    return [str(n) for n in variants[combine(a, b)]

def combine(a, b):
    """Combine the two given numbers using the symbols: *, -, +, /."""
    if a > b: return ('* ' + b + '* ' + a)
    if b > a: return ('*' + a + ' * ' + b)
    if a < b: return ('+' + a + ' + ' + b)
    return ('-' + a + ' - ' + b)
