from collections import defaultdict

def can_paint_edges(n, edges, ants):
    edge_list = defaultdict(list)
    for u, v in edges:
        edge_list[u].append((u, v, False))
        edge_list[v].append((v, u, False))

    def dfs(color, u, visited):
        if color == 0:
            return dfs(1, u, visited)
        for v in visited[u]:
            if not visited[v]:
                visited[v] |= 1
                if dfs(color ^ 1, v, visited):
                    return True
        return False

    used_colors = set()
    for i, (a, b) in enumerate(zip(ants[::2], ants[1::2])):
        visited = [0] * (n + 1)
        visited[a] |= 1
        visited[b] |= 2
        if dfs(0, a, visited):
            return "NO"

    return "YES" if 0 in used_colors else "NO"

