def find_smallest_cost(a, k):
    n = len(a)
    dp = [[float('inf')] * (n + 2) for _ in range(k + 1)]
    dp[0][n] = 0

    for i in range(1, n + 1):
        dp[0][i] = sum(a[:i])

    for i in range(1, n + 1):
        for j in range(1, min(k, i) + 1):
            for l in range(i, j, -1):
                dp[j][i] = min(dp[j][i], dp[j - l][l - 1] + (i - (j - 1)) * a[i - 1] - (l - (i - 1)) * a[l - 1])

    return dp[k][n]

