from functools import lru_cache

MOD = 10**6 + 3

def count_UAE(s):
    @lru_cache(maxsize=None)
    def dp(idx):
        if idx >= len(s):
            return 1
        ans = 0
        for i in range(idx + 1, len(s) + 1):
            x = int(s[idx:i])
            val = dp(i)
            if s[0] == '+':
                ans += val
            elif s[0] == '-':
                ans -= val
            elif s[0] == '*':
                ans += dp(i) * x
            elif s[0] == '/':
                ans += dp(i) // x
        return ans % MOD

    return dp(0) % MOD

