import bisect

def find_peg(lengths, query):
    min_index = bisect.bisect_left(lengths, query[1])
    max_index = min(len(lengths), bisect.bisect_right(lengths, query[1]))

    if query[0] <= min_index:
        return min_index

    if query[0] + 1 <= max_index:
        return max_index

    return bisect.bisect_left(lengths, query[0] * 2) - 1

