    min_cost = 0
    memo = {}

    def dfs(node, parent):
        nonlocal min_cost
        if min_cost < 0:
            return 0
        if memo.get(node) is not None:
            return memo[node]

        ret = 0
        if node != 'if':
            for child in program[str(node).replace("if", "")]:
                if child not in program or not program.get(child):
                    ret += dfs(child, parent)
            memo[node] = ret
            return ret

        if node[0].isdigit():
            num = int(node)

            if num <= s:
                ret += dfs('end', node)
                if ret < 0:
                    return 0
                elif ret > memo['end'] + num:
                    memRejects = deque(dist_from_end(num, parent))
                    for i in range(len(memRejects)):
                        memReject = memRejects.popleft()
                        if memReject[0] == 0 and num + memReject[2] >= s - memReject[1] and dfs(memReject[1], (i == 0) * str(num) + memReject[0]):
                            memo[node] = ret
                            return ret
                        elif not memReject:
                            break
        else:
            if (node[1] == 's' and dfs('if', node) < 0) or dfs('if', node) >= 0:
                for child in program[str(node).replace("end", "")]:
                    if child != node and child[0].isdigit():
                        ret += dfs(str(int(child) - 1), node)
        memo[node] = ret if ret > 0 else -1
        return ret

    if n == 1 and program.get('1'):
        memo['1'] = 0
    if n == 1 and program.get('1') is None:
        memo['1'] = -1
    dist_from_end = deque([(-1, 'end', 'set'), (0, 'set', 'end')]) if program.get('if') else deque()

