def sieve_of_eratosthenes(limit):
    """Generate primes up to a given limit using the Sieve of Eratosthenes."""
    limit_num = limit + 1
    primes = {}
    for i in range(2, limit_num):
        primes[i] = True

    for i in primes:
        if i * i > limit_num:
            break
        for z in range(i * i, limit_num, i):
            primes[z] = False
    return [num for num in primes if primes[num] == True]

def count_matrices(prime):
