from collections import Counter
from bisect import bisect_right

def solve(nums):
    n = len(nums)
    freq_counts = [Counter(nums[i:]).most_common() for i in range(n)]
    closest_freq2diff = [-1] * n
    for i, counts in enumerate(freq_counts):
        if len(counts) < 2:
            continue
        most_common = counts[-1]
        if counts[-2]:
            closest_freq2diff[i] = counts[-2][1] - most_common[1]
    dp = [1] * n
    for i in range(n):
        freq_counts[i][nums[i]] -= 1
        for j in range(i + 1, n):
            freq_counts[j][nums[j]] -= 1
            data = []
            for k in range(n):
                val = freq_counts[k].most_common()[:2]
                if most_common := val[0][1] - val[1][1]:
                    u = 1 if i == k else 0
                    for t, cnt in val:
                        if most_common <= cnt <= closest_freq2diff[k]:
                            continuation = bisect_right(freq_counts[j], [t, cnt + u]) == len(freq_counts[j])
                            if continuation:
                                data.append(continuation)
                    dp[j] = max(dp[j], sum(data) + dp[i])
            freq_counts[i][nums[i]] += 1
            closest_freq2diff = [-1] * n
            for k in range(n):
                freq_counts[k][nums[k]] = 1 if most_common is not None else 0
    return dp[n - 1]

if __name__ == "__main__":
    n = int(input())
    nums = list(map(int, input().split()))
    print(solve(nums))
